//! Parity tests: Rust mel vs. Python HuggingFace reference fixtures.
//!
//! Fixtures in tests/fixtures/ were generated by scripts/gen_mel_fixtures.py
//! using WhisperFeatureExtractor and ClapFeatureExtractor from transformers 4.x.
//! Tolerance: 1e-4 absolute (ADR 0004 requirement).

// Re-export preprocess as pub so we can call it from tests.
// (mel and image are private mod; we expose them here via a test helper.)
mod helpers {
    use std::path::Path;

    pub fn fixture_dir() -> std::path::PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
    }

    pub fn load_f32(name: &str) -> (Vec<usize>, Vec<f32>) {
        let dir = fixture_dir();
        let shape_str = std::fs::read_to_string(dir.join(format!("{name}.shape"))).unwrap();
        let shape: Vec<usize> = shape_str
            .split_whitespace()
            .map(|s| s.parse().unwrap())
            .collect();
        let bytes = std::fs::read(dir.join(format!("{name}.f32"))).unwrap();
        let data: Vec<f32> = bytes
            .chunks_exact(4)
            .map(|b| f32::from_le_bytes([b[0], b[1], b[2], b[3]]))
            .collect();
        (shape, data)
    }

    pub fn max_abs_err(a: &[f32], b: &[f32]) -> f32 {
        assert_eq!(a.len(), b.len(), "length mismatch");
        a.iter()
            .zip(b.iter())
            .map(|(x, y)| (x - y).abs())
            .fold(0.0_f32, f32::max)
    }

    pub fn sine440(n_samples: usize, sample_rate: u32) -> Vec<f32> {
        // Use f64 argument to match numpy's arange+sin precision before casting to f32.
        (0..n_samples)
            .map(|i| {
                (2.0_f64 * std::f64::consts::PI * 440.0 * i as f64 / sample_rate as f64).sin()
                    as f32
            })
            .collect()
    }
}

use helpers::*;

const TOL: f32 = 1e-4;

// ── Whisper parity ─────────────────────────────────────────────────────────

#[test]
fn whisper_zeros_parity() {
    let mel = somnus_encoding::preprocess::mel::WhisperMel::new();
    let pcm = vec![0.0f32; 480_000];
    let got = mel.compute(&pcm);

    let (shape, expected) = load_f32("whisper_zeros");
    assert_eq!(shape, [80, 3000]);
    assert_eq!(got.len(), expected.len());

    let err = max_abs_err(&got, &expected);
    assert!(err < TOL, "whisper zeros max_abs_err={err} >= {TOL}");
}

#[test]
fn whisper_sine440_parity() {
    let mel = somnus_encoding::preprocess::mel::WhisperMel::new();
    let pcm = sine440(480_000, 16_000);
    let got = mel.compute(&pcm);

    let (shape, expected) = load_f32("whisper_sine440");
    assert_eq!(shape, [80, 3000]);

    let err = max_abs_err(&got, &expected);
    assert!(err < TOL, "whisper sine440 max_abs_err={err} >= {TOL}");
}

// ── CLAP parity ────────────────────────────────────────────────────────────

#[test]
fn clap_zeros_parity() {
    let mel = somnus_encoding::preprocess::mel::ClapMel::new();
    let pcm = vec![0.0f32; 480_000];
    let got = mel.compute(&pcm);

    let (shape, expected) = load_f32("clap_zeros");
    assert_eq!(shape, [1001, 64]);
    assert_eq!(got.len(), expected.len());

    let err = max_abs_err(&got, &expected);
    assert!(err < TOL, "clap zeros max_abs_err={err} >= {TOL}");
}

#[test]
fn clap_sine440_parity() {
    let mel = somnus_encoding::preprocess::mel::ClapMel::new();
    let pcm = sine440(480_000, 48_000);
    let got = mel.compute(&pcm);

    let (shape, expected) = load_f32("clap_sine440");
    assert_eq!(shape, [1001, 64]);

    let err = max_abs_err(&got, &expected);
    assert!(err < TOL, "clap sine440 max_abs_err={err} >= {TOL}");
}

// ── DINOv2 image parity ────────────────────────────────────────────────────

fn make_video_frame(
    data: Vec<u8>,
    w: u32,
    h: u32,
    fmt: somnus_sensory::PixelFormat,
) -> somnus_sensory::VideoFrame {
    somnus_sensory::VideoFrame {
        data,
        width: w,
        height: h,
        format: fmt,
        timestamp: somnus_sensory::Timestamp::now(),
    }
}

#[test]
fn dino_black_parity() {
    let frame = make_video_frame(
        vec![0u8; 320 * 240 * 3],
        320,
        240,
        somnus_sensory::PixelFormat::Rgb8,
    );
    let got = somnus_encoding::preprocess::image::frame_to_tensor(&frame).unwrap();

    let (shape, expected) = load_f32("dino_black");
    assert_eq!(shape, [3, 224, 224]);

    let err = max_abs_err(&got, &expected);
    assert!(err < TOL, "dino black max_abs_err={err} >= {TOL}");
}

#[test]
fn dino_gray128_parity() {
    let frame = make_video_frame(
        vec![128u8; 320 * 240 * 3],
        320,
        240,
        somnus_sensory::PixelFormat::Rgb8,
    );
    let got = somnus_encoding::preprocess::image::frame_to_tensor(&frame).unwrap();

    let (shape, expected) = load_f32("dino_gray128");
    assert_eq!(shape, [3, 224, 224]);

    let err = max_abs_err(&got, &expected);
    assert!(err < TOL, "dino gray128 max_abs_err={err} >= {TOL}");
}

#[test]
fn dino_checkerboard_parity() {
    // 240×320 checkerboard with 2×2 tiles alternating black/white
    let mut data = vec![0u8; 240 * 320 * 3];
    for row in 0..240usize {
        for col in 0..320usize {
            let val = if (row + col) % 2 == 0 {
                0u8
            } else {
                255u8
            };
            let base = (row * 320 + col) * 3;
            data[base] = val;
            data[base + 1] = val;
            data[base + 2] = val;
        }
    }
    let frame = make_video_frame(data, 320, 240, somnus_sensory::PixelFormat::Rgb8);
    let got = somnus_encoding::preprocess::image::frame_to_tensor(&frame).unwrap();

    let (shape, expected) = load_f32("dino_checkerboard");
    assert_eq!(shape, [3, 224, 224]);

    let err = max_abs_err(&got, &expected);
    assert!(err < TOL, "dino checkerboard max_abs_err={err} >= {TOL}");
}
